import json
from dataclasses import dataclass
from typing import List
import jsonschema
from mashumaro.jsonschema import build_json_schema


@dataclass
class SimpleInner:
    name: str


@dataclass  
class SimpleOuter:
    items: List[SimpleInner]


def test_references():
    schema = build_json_schema(SimpleOuter, all_refs=True)
    schema_dict = schema.to_dict()

    print("Generated schema:")
    print(json.dumps(schema_dict, indent=2))

    # Test data
    test_data = {
        "items": [
            {"name": "test1"},
            {"name": "test2"}
        ]
    }

    print("\nTest data:")
    print(json.dumps(test_data, indent=2))

    try:
        jsonschema.validate(test_data, schema_dict)
        print("✓ Validation successful!")
    except Exception as e:
        print(f"✗ Validation failed: {e}")

        # Let's manually check if the reference resolves
        defs = schema_dict.get('$defs', {})
        print(f"\nAvailable definitions: {list(defs.keys())}")

        # Try to manually resolve the reference
        ref = schema_dict['properties']['items']['items'].get('$ref')
        if ref:
            print(f"Reference: {ref}")
            if ref.startswith('#/defs/'):
                def_name = ref.split('/')[-1]
                if def_name in defs:
                    print(f"Found definition for {def_name}")
                    print(json.dumps(defs[def_name], indent=2))
                else:
                    print(f"Missing definition for {def_name}")


if __name__ == "__main__":
    test_references()

