#!/usr/bin/env python3

import json
import jsonschema


def test_with_schema_uri():
    # Manually create a schema with proper $schema URI
    manual_schema = {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "type": "object",
        "title": "SimpleOuter",
        "$defs": {
            "SimpleInner": {
                "type": "object",
                "title": "SimpleInner",
                "properties": {
                    "name": {
                        "type": "string"
                    }
                },
                "additionalProperties": False,
                "required": [
                    "name"
                ]
            }
        },
        "properties": {
            "items": {
                "type": "array",
                "items": {
                    "$ref": "#/defs/SimpleInner"
                }
            }
        },
        "additionalProperties": False,
        "required": [
            "items"
        ]
    }

    print("Manual schema with $schema URI:")
    print(json.dumps(manual_schema, indent=2))

    # Test data
    test_data = {
        "items": [
            {"name": "test1"},
            {"name": "test2"}
        ]
    }

    print("\nTest data:")
    print(json.dumps(test_data, indent=2))

    try:
        jsonschema.validate(test_data, manual_schema)
        print("✓ Manual schema validation successful!")
    except Exception as e:
        print(f"✗ Manual schema validation failed: {e}")
        print(f"Error type: {type(e)}")

        # Let's also try with a Resolver
        try:
            resolver = jsonschema.RefResolver.from_schema(manual_schema)
            jsonschema.validate(test_data, manual_schema, resolver=resolver)
            print("✓ Validation with resolver successful!")
        except Exception as e2:
            print(f"✗ Validation with resolver also failed: {e2}")


if __name__ == "__main__":
    test_with_schema_uri()

