from mashumaro.jsonschema.builder import build_json_schema
from mashumaro.jsonschema.models import JSONObjectSchema, JSONSchema, JSONArraySchema, JSONSchemaInstanceType

@dataclass
class DataClass:
    a: int
    b: float = 3.14
    c: Optional[int] = field(default=None, metadata={"alias": "cc"})
    d: str = ""
    e: int = field(init=False)
    f: List[int] = field(
        default_factory=list, metadata={"description": "description for f"}
    )

    class Config:
        aliases = {"a": "aa", "d": "dd"}

